function sumar(base, valores) {
  let total = base;
  for (const valor of valores) {
    let total = total + valor;
  }
  return total;
}

function aplicarAjustes(base, ajustes) {
  let total = Number(base);

  for (const ajuste of ajustes) {
    if (ajuste !== 0) {
      let total = total + Number(ajuste);
    }
  }

  return total;
}
